text:
```yaml
design:
  schema: fpga-design-agent/project/v1
  name: vmed
  board: nexys_a7_100t
  clocks:
    - {name: clk_sys, source: board, port: CLK100MHZ, mhz: 100}
    - {name: pix_clk, source: mmcm, from: clk_sys, mhz: 74.25}
  resets:
    - {name: rst_sys, domain: clk_sys, polarity: active_high, style: sync, from: CPU_RESETN, via: reset_sync}
    - {name: rst_pix, domain: pix_clk, polarity: active_high, style: sync, from: rst_sys, via: reset_sync}
  shell: {design_id: VMED, clock: clk_sys, reset: rst_sys}
  modules:
    - name: clock_gen
      kind: ipgen
      clocks: {clk: clk_sys}
      resets: {rst: rst_sys}
    - name: raster_source
      kind: rtl
      clocks: {clk: pix_clk}
      resets: {rst: rst_pix}
      window_base: 0x00
      register_crossings: {PATTERN: xpm_cdc_single, FRAME_COUNT: xpm_cdc_gray}
    - name: median_filter
      kind: rtl
      clocks: {clk: pix_clk}
      resets: {rst: rst_pix}
    - name: video_output
      kind: rtl
      clocks: {clk: pix_clk}
      resets: {rst: rst_pix}
  connections:
    - {from: raster_source.out, to: median_filter.in}
    - {from: median_filter.out, to: video_output.in}
  board_ports:
    - {name: CLK100MHZ, dir: in, drive: input, to: clk_sys}
    - {name: CPU_RESETN, dir: in, drive: input, to: rst_sys}
    - {name: BTNC, dir: in, drive: input, to: video_output.button}
    - {name: UART_TXD_IN, dir: in, drive: input, to: shell.uart_rx}
    - {name: UART_RXD_OUT, dir: out, drive: push-pull, from: shell.uart_tx}
    - {name: LED[0], dir: out, drive: push-pull, from: pix_clk.locked}
    - {name: VGA_HS, dir: out, drive: push-pull, from: video_output.hsync}
    - {name: VGA_VS, dir: out, drive: push-pull, from: video_output.vsync}
    - {name: "VGA_R[3:0]", dir: out, drive: push-pull, from: video_output.red}
    - {name: "VGA_G[3:0]", dir: out, drive: push-pull, from: video_output.green}
    - {name: "VGA_B[3:0]", dir: out, drive: push-pull, from: video_output.blue}
  owned: []
  assumptions:
    - {id: A-1, text: "Checkerboard tile size", default: "32 x 32 active pixels", reason: "The specification selects a checkerboard pattern but does not define its tile size.", affects: [raster_source.contract.data_formats, raster_source.contract.registers], status: open}
    - {id: A-2, text: "UART command spelling", default: "ID, PATTERN <0|1>, and FRAME commands with newline-terminated ASCII responses", reason: "The answer specifies ASCII commands and newline termination but does not give command spellings or response payload syntax.", affects: [fpga_shell], status: open}
    - {id: A-3, text: "Reset source and implementation", default: "Use CPU_RESETN and synchronize an active-high reset separately in the system and pixel-clock domains.", reason: "The specification does not select a reset source or reset synchronization scheme.", affects: [design.resets.rst_sys, design.resets.rst_pix], status: open}
    - {id: A-4, text: "Button polarity and sampling", default: "Treat BTNC high as pressed and synchronize it into the pixel-clock domain.", reason: "The specification names BTNC but does not state its polarity or synchronization behavior.", affects: [video_output.contract.ports.button], status: open}
    - {id: A-5, text: "Scalar internal wiring", default: "Wire pix_clk.locked to video_output.clock_stable in the integrated top.", reason: "The project connection schema describes interface connections; this lock indication is a scalar control connection.", affects: [video_output.contract.ports.clock_stable], status: open}

contracts:
  clock_gen:
    schema: fpga-design-agent/contract/v1
    module: clock_gen
    summary: Generates the pixel clock and exposes its lock indication.
    clocks:
      - {name: clk, port: clk_in, max_mhz: 100}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk_in, dir: in}
      - {name: rst, dir: in}
      - {name: pixel_clk, dir: out}
      - {name: locked, dir: out}
  raster_source:
    schema: fpga-design-agent/contract/v1
    module: raster_source
    summary: Generates 720p60 raster timing, selectable test-pattern pixels, and a completed-frame counter.
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: pattern_sel, dir: in, width: 1, clock: clk}
      - {name: frame_count, dir: out, width: 32, clock: clk, reset_value: 0}
      - {name: m_axis_tvalid, dir: out, clock: clk, reset_value: 0}
      - {name: m_axis_tready, dir: in, clock: clk}
      - {name: m_axis_tdata, dir: out, width: 12, clock: clk}
      - {name: m_axis_tuser, dir: out, width: 3, clock: clk}
      - {name: m_axis_tlast, dir: out, clock: clk}
    data_formats:
      - {name: rgb12, format: u12, packing: "R[11:8], G[7:4], B[3:0]"}
    interfaces:
      - name: out
        protocol: axi4-stream
        role: master
        prefix: m_axis
        clock: clk
        reset: rst
        tdata: {width: 12, fields: [{name: rgb, bits: [11, 0], format: rgb12}]}
        tuser:
          - {bit: 0, name: active, meaning: "1 for an active-picture pixel"}
          - {bit: 1, name: hsync, meaning: "Horizontal sync level for this raster pixel"}
          - {bit: 2, name: vsync, meaning: "Vertical sync level for this raster pixel"}
        tlast: "Asserted on the final pixel clock of each line."
        packet_beats: 1650
        backpressure: false
        source_gaps: false
    registers:
      bus: top
      map:
        - {name: PATTERN, offset: 0x00, access: RW, reset: 0, width: 1, volatile: false, fields: [{name: pattern_sel, bits: [0, 0], port: pattern_sel}]}
        - {name: FRAME_COUNT, offset: 0x04, access: RO, reset: 0, width: 32, volatile: true, fields: [{name: frame_count, bits: [31, 0], port: frame_count}]}
  median_filter:
    schema: fpga-design-agent/contract/v1
    module: median_filter
    summary: Applies a per-channel 3 x 3 median filter while preserving raster metadata.
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: s_axis_tvalid, dir: in, clock: clk}
      - {name: s_axis_tready, dir: out, clock: clk}
      - {name: s_axis_tdata, dir: in, width: 12, clock: clk}
      - {name: s_axis_tuser, dir: in, width: 3, clock: clk}
      - {name: s_axis_tlast, dir: in, clock: clk}
      - {name: m_axis_tvalid, dir: out, clock: clk, reset_value: 0}
      - {name: m_axis_tready, dir: in, clock: clk}
      - {name: m_axis_tdata, dir: out, width: 12, clock: clk}
      - {name: m_axis_tuser, dir: out, width: 3, clock: clk}
      - {name: m_axis_tlast, dir: out, clock: clk}
    data_formats:
      - {name: rgb12, format: u12, packing: "R[11:8], G[7:4], B[3:0]"}
    interfaces:
      - name: in
        protocol: axi4-stream
        role: slave
        prefix: s_axis
        clock: clk
        reset: rst
        tdata: {width: 12, fields: [{name: rgb, bits: [11, 0], format: rgb12}]}
        tuser:
          - {bit: 0, name: active, meaning: "1 for an active-picture pixel"}
          - {bit: 1, name: hsync, meaning: "Horizontal sync level for this raster pixel"}
          - {bit: 2, name: vsync, meaning: "Vertical sync level for this raster pixel"}
        tlast: "Asserted on the final pixel clock of each line."
        packet_beats: 1650
        backpressure: false
        source_gaps: false
      - name: out
        protocol: axi4-stream
        role: master
        prefix: m_axis
        clock: clk
        reset: rst
        tdata: {width: 12, fields: [{name: rgb, bits: [11, 0], format: rgb12}]}
        tuser:
          - {bit: 0, name: active, meaning: "1 for an active-picture pixel"}
          - {bit: 1, name: hsync, meaning: "Horizontal sync level for this raster pixel"}
          - {bit: 2, name: vsync, meaning: "Vertical sync level for this raster pixel"}
        tlast: "Asserted on the final pixel clock of each line."
        packet_beats: 1650
        backpressure: false
        source_gaps: false
  video_output:
    schema: fpga-design-agent/contract/v1
    module: video_output
    summary: Drives VGA sync and RGB pins, blanking colour when required.
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: button, dir: in, clock: async}
      - {name: clock_stable, dir: in, clock: async}
      - {name: s_axis_tvalid, dir: in, clock: clk}
      - {name: s_axis_tready, dir: out, clock: clk}
      - {name: s_axis_tdata, dir: in, width: 12, clock: clk}
      - {name: s_axis_tuser, dir: in, width: 3, clock: clk}
      - {name: s_axis_tlast, dir: in, clock: clk}
      - {name: red, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: green, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: blue, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: hsync, dir: out, clock: clk, reset_value: 0}
      - {name: vsync, dir: out, clock: clk, reset_value: 0}
    data_formats:
      - {name: rgb12, format: u12, packing: "R[11:8], G[7:4], B[3:0]"}
    interfaces:
      - name: in
        protocol: axi4-stream
        role: slave
        prefix: s_axis
        clock: clk
        reset: rst
        tdata: {width: 12, fields: [{name: rgb, bits: [11, 0], format: rgb12}]}
        tuser:
          - {bit: 0, name: active, meaning: "1 for an active-picture pixel"}
          - {bit: 1, name: hsync, meaning: "Horizontal sync level for this raster pixel"}
          - {bit: 2, name: vsync, meaning: "Vertical sync level for this raster pixel"}
        tlast: "Asserted on the final pixel clock of each line."
        packet_beats: 1650
        backpressure: false
        source_gaps: false

module_specs:
  clock_gen: |
    Generate a nominal 74.25 MHz pixel clock from the 100 MHz board clock and expose the clock generator lock indication. The integrated design uses the lock indication for LED[0] and for output blanking.
  raster_source: |
    Generate the complete 1650-clock by 750-line raster with 1280 by 720 active pixels, positive syncs, and the specified porches. Pattern select 0 produces the specified colour bars; pattern select 1 produces a checkerboard. Emit one stream beat for every raster pixel clock, carrying RGB plus active, hsync, and vsync metadata. Increment the 32-bit frame counter once per completed frame; reset it to zero and allow natural unsigned wraparound.
  median_filter: |
    For each active output pixel and each RGB channel, calculate the median of that channel's 3 x 3 active-picture neighbourhood. Replicate the nearest active-edge pixel when the neighbourhood extends beyond the active picture. Preserve raster metadata and align the filtered picture with its sync signals. Do not stall the raster stream.
  video_output: |
    Drive VGA sync from the stream metadata and drive the four-bit RGB channels from the filtered pixel data. Drive RGB to zero outside the active picture, while the synchronized centre button is pressed, or while the synchronized clock-stable indication is false. Keep sync outputs aligned with the pixel stream.

requirements:
  - id: S-1
    text: "Generate VGA timing at 1280 x 720 active pixels and 60 Hz using a nominal 74.25 MHz pixel clock, 1650 pixel clocks per line (1280 active, 110 front porch, 40 sync, 220 back porch), and 750 lines per frame (720 active, 5 front porch, 5 sync, 20 back porch), with positive horizontal and vertical sync."
    proof: [simulation, hardware, analysis]
    modules: [clock_gen, raster_source, video_output, top]
  - id: S-2
    text: "With the default pattern selected, display eight vertical bars, each 160 active pixels wide, in this order: white, yellow, cyan, green, magenta, red, blue, black."
    proof: [simulation, hardware]
    modules: [raster_source, video_output, top]
  - id: S-3
    text: "For each output pixel and each colour channel, produce the median of that channel's nine samples in the corresponding 3 x 3 input neighbourhood."
    proof: [simulation, formal]
    modules: [median_filter]
  - id: S-4
    text: "Keep the filtered picture aligned with the VGA sync signals so that filtering does not shift the picture's active region relative to the specified video timing."
    proof: [simulation, hardware]
    modules: [raster_source, median_filter, video_output]
  - id: S-5
    text: "Drive all colour outputs to zero outside the active picture, while BTNC is pressed, or while the pixel clock is not stable."
    proof: [simulation, hardware]
    modules: [video_output, top]
  - id: S-6
    text: "Illuminate LED[0] when the pixel clock is stable and leave it unilluminated when the pixel clock is not stable."
    proof: [simulation, hardware]
    modules: [clock_gen, top]
  - id: S-7
    text: "Provide a USB-UART test shell operating at 115200 baud that identifies the design as VMED, allows the host to select a test pattern, and allows the host to read a frame counter."
    proof: [simulation, hardware]
    modules: [raster_source, top]

