  design.shell.design_id: "design ID \"VMED\""
  design.modules.raster_source.window_base: "a register window at 0x80-0xFF; a module's registers on `bus: top` are placed in that window at `window_base`."
  clock_gen.contract.clocks.clk.max_mhz: "74.25 MHz pixel clock"
