      - name: out
        protocol: axi4-stream
        role: master
        prefix: m_axis
        clock: clk
        reset: rst
        tdata: {width: 12, fields: [{name: rgb, bits: [11, 0], format: rgb12}]}
        tuser:
          - {bit: 0, name: active, meaning: "1 for an active-picture pixel"}
